body.query:
*[
	_type == 'group' &&
	slug.current == $slug &&
	defined(department->slug.current) &&
	department->slug.current == $department
][0] {
	_id,
	description,
	featuredImage,
	heroImage,
	images,
	"isTeamSport": department->isTeamSport,
	meta { metaTitle, metaDescription, openGraphImage},
	title,
	training {
		trainingDescription,
		trainingTimes[] {
			...,
			venue->
		}
	}
}
